object Strings {
    val LANGS = listOf("ja", "en", "fr", "de", "it", "es", "ru", "pt", "pl", "ko", "zh-Hans", "zh-Hant")
    val LANG_NAMES = mapOf(
        "ja" to "日本語", "en" to "English", "fr" to "Français", "de" to "Deutsch",
        "it" to "Italiano", "es" to "Español", "ru" to "Русский", "pt" to "Português",
        "pl" to "Polski", "ko" to "한국어", "zh-Hans" to "简体中文", "zh-Hant" to "繁體中文")

    fun resolve(saved: String?, systemLang: String?): String {
        if (saved != null && saved in LANGS) return saved
        val s = (systemLang ?: "").lowercase()
        return when {
            s.startsWith("ja") -> "ja"
            s.startsWith("fr") -> "fr"
            s.startsWith("de") -> "de"
            s.startsWith("it") -> "it"
            s.startsWith("es") -> "es"
            s.startsWith("ru") -> "ru"
            s.startsWith("pt") -> "pt"
            s.startsWith("pl") -> "pl"
            s.startsWith("ko") -> "ko"
            s.startsWith("zh") -> if (s.contains("hant") || s.contains("tw") || s.contains("hk")) "zh-Hant" else "zh-Hans"
            else -> "en"
        }
    }

    var lang: String = "ja"
    fun t(key: String): String = MAPS[lang]?.get(key) ?: MAPS["en"]?.get(key) ?: key

